// 真实目录和原完整来源同一World借用，保存点仍只含原Director调度/计划，不写任何新承诺。
#include "visit_appointment_attendance_world.hpp"
#include "resident/kernel/world_bundle.hpp"
namespace hanmo::resident {
Outcome<std::optional<VisitAppointmentAttendanceRead>> visit_appointment_attendance_read_world(const WorldBundle& w){if(!w.catalog->visit_appointment_attendance)return {true,std::nullopt,{}};if(!w.dynamic_enabled()||!w.catalog->interaction||!w.catalog->visit_appointment_invitations||!w.interaction.visit_appointment_invitations||!w.interaction.visit_appointment_meetings||!w.catalog->personal_appointments||!w.catalog->director||!w.catalog->director->personal_appointment_attendance)return {false,{},common_failure("VisitAppointmentAttendanceProfileRequired").error};auto valid=validate_visit_appointment_attendance_catalog(*w.catalog->visit_appointment_attendance,*w.catalog->visit_appointment_invitations,*w.catalog->director->personal_appointment_attendance,*w.catalog->personal_appointments);if(!valid.ok)return {false,{},valid.error};return {true,VisitAppointmentAttendanceRead{w.common,w.interaction,w.tasks,*w.catalog->visit_appointment_invitations,*w.interaction.visit_appointment_invitations,*w.interaction.visit_appointment_meetings,*w.catalog->personal_appointments,*w.catalog->director->personal_appointment_attendance},{}};}
Status validate_visit_appointment_attendance_world(const WorldBundle& w){Integer count=0;for(const auto& entry:w.catalog->identity.module_versions)if(entry.first==visit_appointment_attendance_module){++count;if(entry.second!="1")return common_failure("UnsupportedVisitAppointmentAttendanceVersion");}if(count!=(w.catalog->visit_appointment_attendance?1:0))return common_failure("VisitAppointmentAttendanceProfileMismatch");auto read=visit_appointment_attendance_read_world(w);if(!read.ok)return {false,{},read.error};const VisitAppointmentState empty;const auto& state=w.interaction.visit_appointment_invitations?*w.interaction.visit_appointment_invitations:empty;for(const auto* plans:{&w.director.plans,&w.director.archived_plans})for(const auto& row:plans->rows()){auto valid=validate_visit_appointment_attendance_plan(w.common,state,w.catalog->visit_appointment_attendance.get(),row.second);if(!valid.ok)return valid;}return common_success();}
Status wake_visit_appointment_attendance_world(WorldBundle& w){auto read=visit_appointment_attendance_read_world(w);if(!read.ok)return {false,{},read.error};if(!read.value)return common_success();return wake_visit_appointment_attendance(*read.value,*w.catalog->visit_appointment_attendance,*w.catalog->director,w.director);}
}
